mapper.select:
select a.id, a.account_name, a.api_key_no, case when a.api_key is null or a.api_key = '' then '' when char_length(a.api_key) <= 8 then '********' else concat(left(a.api_key, 4), '****', right(a.api_key, 4)) end as api_key, a.supplier_id, s.name as supplier_name, a.status, a.type, a.pull_channel, a.pull_url, a.pull_user, a.creator, cu.user_name as creator_name, a.create_time, a.updater, uu.user_name as updater_name, a.update_time from crm_supplier_account a left join crm_supplier s on a.supplier_id = s.id left join sys_user cu on a.creator = cu.user_id left join sys_user uu on a.updater = uu.user_id
and a.account_name like concat('%', #{accountName}, '%')
and a.api_key_no like concat('%', #{apiKeyNo}, '%')
and a.supplier_id = #{supplierId}
and a.status = #{status}
and a.type = #{type}
order by a.create_time desc, a.id desc

select a.id, a.account_name, a.api_key_no, a.api_key, a.supplier_id, a.status, a.type, a.pull_channel, a.pull_url, a.pull_user from crm_supplier_account a
and a.id = #{accountId}
and a.supplier_id = #{supplierId}
and a.status = 1
order by a.supplier_id, a.id

select count(1) from crm_supplier_account
where supplier_id = #{supplierId}
  and account_name = #{accountName}

    and id != #{excludeId}

mapper.update:
update crm_supplier_account
account_name = #{accountName}, account_pwd = #{accountPwd}, api_key_no = #{apiKeyNo}, api_key = #{apiKey}, supplier_id = #{supplierId}, status = #{status}, type = #{type}, pull_channel = #{pullChannel}, pull_url = #{pullUrl}, pull_user = #{pullUser}, updater = #{updater}, update_time = sysdate(),
where id = #{id}
